type StudyNote = { title: string; nextStep: string };

const note: StudyNote = {
  title: "今天终于理解了一个小问题",
  nextStep: "明天试着不用笔记讲一遍",
};

const summary = ["今天的笔记", note.title, "下一步", note.nextStep, "只记录已经理解的部分，把暂时没有答案的问题留在旁边；下次回来时，从这句话继续就好，不必重新整理整份资料。"].join(" · ");
console.log(summary);
